class ObfuscatedTO {
  #plain = new Map();                        // unprotected pairs
  #masked = new Map();                       // protected pairs, dropped after seal
  #sealed;                                   // { iv, tag, data }

  seal(key) {
    const iv = randomBytes(12);
    const c = createCipheriv('aes-256-gcm', key, iv);
    const data = Buffer.concat([c.update(JSON.stringify([...this.#masked])), c.final()]);
    this.#sealed = { iv, tag: c.getAuthTag(), data };
    this.#masked.clear();                    // drop the plaintext copy
  }
  toJSON() { return { id: this.id, ...Object.fromEntries(this.#plain) }; }
}
